<?php declare(strict_types=1);$fmt=static fn($v)=>$v===null?'—':number_format((float)$v,2,',','.').'e';$labels=['wts_below'=>'WTS onder','wtb_above'=>'WTB boven','spread_above'=>'Spread boven','new_offer'=>'Nieuwe activiteit'];?><section class="page-intro"><div><span class="kicker">PERSOONLIJK</span><h1>Prijsalerts</h1><p>Ontvang alleen een nieuwe melding wanneer een ingestelde conditie opnieuw geraakt wordt.</p></div><div class="actions"><a class="btn secondary" href="/watchlist">Watchlist</a><span class="badge trade"><?=(int)$unread?> ongelezen</span></div></section><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif;?><?php if($result):?><div class="notice success"><?=(int)$result['checked']?> gecontroleerd · <?=(int)$result['triggered']?> nieuw</div><?php endif;?><div class="grid"><section class="surface"><div class="section-heading"><h2>Nieuwe alert</h2></div><form method="post" class="formgrid"><input type="hidden" name="action" value="create"><label class="wide">Marktvariant<select name="market_key" required><option value="">Kies een markt</option><?php foreach($markets as$m):?><option value="<?=h($m['market_key'])?>"><?=h($m['item']??$m['market_key'])?></option><?php endforeach;?></select></label><label>Label<input name="label"></label><label>Conditie<select name="condition_type"><option value="wts_below">WTS onder drempel</option><option value="wtb_above">WTB boven drempel</option><option value="spread_above">Spread boven drempel</option><option value="new_offer">Nieuwe activiteit</option></select></label><label>Drempel in ecto<input name="threshold_ecto" inputmode="decimal"></label><div class="wide"><button class="btn">Opslaan</button></div></form></section><aside class="surface"><div class="section-heading"><h2>Controle</h2></div><div class="actions"><form method="post"><input type="hidden" name="action" value="evaluate"><button class="btn">Nu controleren</button></form><form method="post"><input type="hidden" name="action" value="read_all"><button class="btn secondary">Alles gelezen</button></form></div><p class="muted">Automatische verwerking loopt via cron/evaluate-alerts.php.</p></aside></div><section class="surface"><div class="section-heading"><h2>Mijn alerts</h2><span class="muted"><?=count($alerts)?></span></div><div class="tablewrap"><table><thead><tr><th>Alert</th><th>Conditie</th><th>Status</th><th>Doel</th><th>Acties</th></tr></thead><tbody><?php if(!$alerts):?><tr><td colspan="5" class="muted">Nog geen alerts.</td></tr><?php endif;?><?php foreach($alerts as$r):?><tr><td><strong><?=h((string)($r['label']?:($r['item']??$r['market_key'])))?></strong><small class="muted" style="display:block"><?=h($r['market_key'])?></small></td><td><?=h($labels[$r['condition_type']]??$r['condition_type'])?> <?= $r['threshold_ecto']!==null?h($fmt($r['threshold_ecto'])):''?></td><td><span class="badge <?=(int)$r['is_enabled']===1?'buy':'trade'?>"><?=(int)$r['is_enabled']===1?'Actief':'Pauze'?></span></td><td><?=(int)$r['condition_met']===1?'Geraakt':'Wachten'?></td><td><div class="actions"><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn secondary">Pauze</button></form><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn danger">Wissen</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="surface"><div class="section-heading"><h2>Recente meldingen</h2></div><?php if(!$events):?><p class="muted">Nog geen meldingen.</p><?php endif;?><?php foreach($events as$e):?><article class="event-card <?=(int)$e['is_read']===0?'unread':''?>"><div><strong><?=h($e['message'])?></strong><small><?=h($e['created_at'])?></small></div><?php if((int)$e['is_read']===0):?><form method="post"><input type="hidden" name="action" value="read"><input type="hidden" name="event_id" value="<?=(int)$e['id']?>"><button class="btn secondary">Gelezen</button></form><?php endif;?></article><?php endforeach;?></section>